package org.updraft.betterstatus.bungee;
import com.google.common.io.ByteArrayDataInput;import com.google.common.io.ByteStreams;import net.md_5.bungee.api.*;import net.md_5.bungee.api.config.ServerInfo;import net.md_5.bungee.api.connection.Server;import net.md_5.bungee.api.event.PluginMessageEvent;import net.md_5.bungee.api.plugin.*;import net.md_5.bungee.config.*;import net.md_5.bungee.event.EventHandler;import org.updraft.betterstatus.model.*;import org.updraft.betterstatus.monitor.*;import org.updraft.betterstatus.protocol.StatusProtocol;import org.updraft.betterstatus.storage.HistoryStore;import org.updraft.betterstatus.notify.DiscordNotifier;import java.io.*;import java.nio.file.Files;import java.util.*;import java.util.concurrent.*;
public final class BungeeStatusPlugin extends Plugin implements Listener {
 private MonitorEngine monitor;private HistoryStore history;private ExecutorService alerts;private DiscordNotifier discord;private String online,offline,maintenance;
 @Override public void onEnable(){try{if(!getDataFolder().exists())getDataFolder().mkdirs();File file=new File(getDataFolder(),"config.yml");if(!file.exists())try(InputStream in=getResourceAsStream("config.yml")){if(in!=null)Files.copy(in,file.toPath());}Configuration c=ConfigurationProvider.getProvider(YamlConfiguration.class).load(file);online=color(c.getString("messages.online","&aOnline"));offline=color(c.getString("messages.offline","&cOffline"));maintenance=color(c.getString("messages.maintenance","&6Maintenance"));MonitorConfig mc=new MonitorConfig(c.getLong("settings.update-interval-seconds",5)*1000,c.getLong("settings.timeout-millis",3000),c.getInt("settings.failure-threshold",3),c.getInt("settings.recovery-threshold",2),c.getLong("settings.warning-ping-millis",150),c.getLong("settings.critical-ping-millis",300));Map<String,PingProvider> providers=new LinkedHashMap<>();for(String n:c.getStringList("servers")){ServerInfo info=getProxy().getServerInfo(n);if(info!=null)providers.put(n,()->ping(info));else getLogger().warning("Unknown configured server: "+n);}monitor=new MonitorEngine(providers,mc);alerts=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"BetterStatus-Alerts");t.setDaemon(true);return t;});discord=new DiscordNotifier(c.getString("discord.webhook-url",""),alerts);if(c.getBoolean("storage.enabled",true))try{history=new HistoryStore("jdbc:sqlite:"+new File(getDataFolder(),"history.db").getAbsolutePath());}catch(Exception e){getLogger().warning("History disabled: "+e.getMessage());}monitor.addListener((a,b)->{if(history!=null)try{history.record(b);}catch(Exception ignored){}discord.sendTransition(a,b);});getProxy().getPluginManager().registerListener(this,this);getProxy().getPluginManager().registerCommand(this,new StatusCommand());monitor.start();getLogger().info("BetterStatus enabled; monitoring "+providers.size()+" server(s).");}catch(Exception e){getLogger().severe("BetterStatus failed to start: "+e.getMessage());}}
 private CompletableFuture<PingResult> ping(ServerInfo info){long start=System.nanoTime();CompletableFuture<PingResult> f=new CompletableFuture<>();info.ping((p,e)->{if(e!=null||p==null){f.complete(PingResult.failure(e==null?"No response":e.getClass().getSimpleName()));return;}int online=p.getPlayers()==null?0:p.getPlayers().getOnline(),max=p.getPlayers()==null?0:p.getPlayers().getMax();String motd=p.getDescriptionComponent()==null?"":net.md_5.bungee.api.chat.TextComponent.toLegacyText(p.getDescriptionComponent());String version=p.getVersion()==null?"":p.getVersion().getName();f.complete(new PingResult(true,online,max,TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start),motd,version,""));});return f;}
 @EventHandler public void onPluginMessage(PluginMessageEvent e){if(!"BungeeCord".equals(e.getTag())||!(e.getSender() instanceof Server server))return;try{ByteArrayDataInput in=ByteStreams.newDataInput(e.getData());if(!StatusProtocol.SUBCHANNEL.equals(in.readUTF()))return;server.sendData("BungeeCord",StatusProtocol.encode(monitor.getServers(),online,offline,maintenance));}catch(Exception ex){getLogger().warning("Rejected invalid status request");}}
 private String color(String s){return s.replace('&','§');}
 @Override public void onDisable(){if(monitor!=null)monitor.close();if(history!=null)try{history.close();}catch(Exception ignored){}if(alerts!=null)alerts.shutdownNow();}
 private final class StatusCommand extends Command{StatusCommand(){super("srvstatus","serverstatus.admin","ss");}public void execute(CommandSender sender,String[] a){if(a.length==0||a[0].equalsIgnoreCase("list")){for(ServerSnapshot s:monitor.getServers())sender.sendMessage("§7"+s.name()+": "+s.state()+" §8("+s.players()+"/"+s.maxPlayers()+", "+s.pingMillis()+"ms)");}else if(a[0].equalsIgnoreCase("check")){if(a.length<2||a[1].equalsIgnoreCase("all"))monitor.refreshAll();else monitor.checkServer(a[1]);sender.sendMessage("§aCheck queued.");}else if(a[0].equalsIgnoreCase("info")&&a.length>1)monitor.getServer(a[1]).ifPresentOrElse(s->sender.sendMessage(s.toString()),()->sender.sendMessage("§cUnknown server."));else if(a[0].equalsIgnoreCase("history")&&a.length>1&&history!=null)try{history.recent(a[1],10).forEach(sender::sendMessage);}catch(Exception ex){sender.sendMessage("§cHistory unavailable.");}else sender.sendMessage("§e/srvstatus [list|info <server>|check <server|all>|history <server>]");}}
}